S = input()

ans = 0
balance = 0
min_balance = 0

# Calculate the balance of parentheses
for char in S:
    if char == '(':
        balance += 1
    else:
        balance -= 1
    min_balance = min(min_balance, balance)

# Calculate the number of swaps or replacements needed
if balance != 0:
    if A < 2 * B:
        ans += A * abs(balance) // 2
    else:
        ans += B * abs(balance)

# Calculate the cost to fix the minimum balance
if min_balance < 0:
    ans += min(A * abs(min_balance), 2 * B * abs(min_balance))

print(ans)

